<?php
function smtp_line($fp) { $l=''; while (($c=fgets($fp,515))!==false) { $l.=$c; if (substr($c,-1)==="\n") break; } return trim($l); }
function smtp_ok($fp, $codes) { return in_array((int)substr(smtp_line($fp),0,3), (array)$codes, true); }
function smtp_cmd($fp, $cmd, $codes) { fwrite($fp, $cmd."\r\n"); return smtp_ok($fp, $codes); }
function send_mail_smtp($to, $subject, $body) { if (!defined('MAIL_ENABLED') || !MAIL_ENABLED) return false; $remote = (MAIL_ENCRYPTION==='ssl') ? 'ssl://'.MAIL_HOST : MAIL_HOST; $fp = @stream_socket_client($remote.':'.MAIL_PORT, $en, $es, 20); if (!$fp) return false; stream_set_timeout($fp, 20); if (!smtp_ok($fp,[220])) { fclose($fp); return false; } smtp_cmd($fp,'EHLO localhost',[250]); if (MAIL_ENCRYPTION==='tls') { if (!smtp_cmd($fp,'STARTTLS',[220])) { fclose($fp); return false; } stream_socket_enable_crypto($fp,true,STREAM_CRYPTO_METHOD_TLS_CLIENT); smtp_cmd($fp,'EHLO localhost',[250]); } if (MAIL_USER!=='') { if (!smtp_cmd($fp,'AUTH LOGIN',[334]) || !smtp_cmd($fp,base64_encode(MAIL_USER),[334]) || !smtp_cmd($fp,base64_encode(MAIL_PASS),[235])) { fclose($fp); return false; } } if (!smtp_cmd($fp,'MAIL FROM:<' . MAIL_FROM . '>',[250]) || !smtp_cmd($fp,'RCPT TO:<'.$to.'>',[250,251]) || !smtp_cmd($fp,'DATA',[354])) { fclose($fp); return false; } $h = 'From: '.MAIL_FROM_NAME.' <'.MAIL_FROM.">\r\nTo: <".$to.">\r\nSubject: =?UTF-8?B?".base64_encode($subject)."?=\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\nDate: ".date('r')."\r\n"; fwrite($fp, str_replace("\n.","\n..",$h."\r\n".$body."\r\n.")."\r\n"); if (!smtp_ok($fp,[250])) { fclose($fp); return false; } smtp_cmd($fp,'QUIT',[221]); fclose($fp); return true; }
